#!/usr/bin/env node

// Regenerates the auto-generated "Library compatibility" section of
// apps/docs/reference/support-matrix.md from the vifx compatibility runner's
// library matrix. The section is delimited by HTML marker comments so the rest
// of the page (and sibling edits) are left untouched.
//
// Usage:
//   node scripts/generate-support-matrix.mjs          # write the section
//   node scripts/generate-support-matrix.mjs --check   # fail if out of date
//
// Requires @vifx/compat-runner to be built first (pnpm --filter @vifx/compat-runner run build).

import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL, fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const docPath = path.join(repoRoot, "apps", "docs", "reference", "support-matrix.md");

// Import the built runner directly: the repo root is not a workspace member, so
// @vifx/* package specifiers are not resolvable here (matching the convention in
// scripts/bootstrap-local-cli.mjs).
const compatRunnerEntry = path.join(repoRoot, "packages", "compat-runner", "dist", "index.mjs");
const { runCompatSuite } = await import(pathToFileURL(compatRunnerEntry).href);

const BEGIN_MARKER = "<!-- BEGIN AUTO-GENERATED: library-compat-matrix -->";
const END_MARKER = "<!-- END AUTO-GENERATED: library-compat-matrix -->";

const STATUS_LEGEND = {
  pass: "Resolves and bundles from the synthetic package sources with no build-time-invisible gaps.",
  partial:
    "JavaScript resolves and bundles, but a build cannot exercise a native module, worklet compilation, or a CSS/Babel transform.",
  fail: "The default build cannot produce a bundle (for example, untranspiled JSX shipped in a published `.js` file).",
  skip: "Not exercised by this toolchain.",
};

// Make a value safe inside a GFM table cell rendered by VitePress (which parses
// Markdown as Vue): escape pipes, and neutralize angle brackets and `{{ }}`
// interpolation so adapter-provided text can never break `docs build`.
function toMarkdownCell(value) {
  return value
    .replace(/\|/g, "\\|")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\{\{/g, "&#123;&#123;");
}

// Render a GFM table with column-aligned cells matching the oxfmt style, so the
// generated section is already formatter-stable (vp check / --check agree).
function formatTable(headers, rows) {
  const widths = headers.map((header, column) =>
    Math.max(header.length, ...rows.map((cells) => cells[column].length)),
  );
  const renderRow = (cells) =>
    `| ${cells.map((cell, column) => cell.padEnd(widths[column])).join(" | ")} |`;
  const separator = `| ${widths.map((width) => "-".repeat(width)).join(" | ")} |`;
  return [renderRow(headers), separator, ...rows.map(renderRow)];
}

function buildSection(vifxReport) {
  const counts = vifxReport.libraryMatrix.reduce((acc, row) => {
    acc[row.status] = (acc[row.status] ?? 0) + 1;
    return acc;
  }, {});

  const legendTable = formatTable(
    ["Status", "Meaning"],
    [
      ["pass", STATUS_LEGEND.pass],
      ["partial", STATUS_LEGEND.partial],
      ["fail", STATUS_LEGEND.fail],
      ["skip", STATUS_LEGEND.skip],
    ],
  );

  const matrixTable = formatTable(
    ["Library", "vifx status", "Detail"],
    vifxReport.libraryMatrix.map((row) => [
      `\`${row.packageName}\``,
      row.status,
      toMarkdownCell(row.detail),
    ]),
  );

  return [
    BEGIN_MARKER,
    "",
    "## Library Compatibility",
    "",
    "_Auto-generated by `scripts/generate-support-matrix.mjs` from the `@vifx/compat-runner` library matrix. Do not edit by hand; run `pnpm docs:support-matrix` to refresh._",
    "",
    "Each library is a synthetic fixture replicating the real package's publishing quirks (exports maps, `react-native` fields at TypeScript sources, JSX/Flow in published `.js`, native-module imports, CSS entries). The status is what the Vifx bundler corridor produces today; the live Metro reference adapter records every library as `skip` because it is never spawned.",
    "",
    `Snapshot for the \`vifx\` toolchain: ${counts.pass ?? 0} pass, ${counts.partial ?? 0} partial, ${counts.fail ?? 0} fail (of ${vifxReport.libraryMatrix.length}).`,
    "",
    ...legendTable,
    "",
    ...matrixTable,
    "",
    END_MARKER,
  ].join("\n");
}

function spliceSection(existing, section) {
  const beginIndex = existing.indexOf(BEGIN_MARKER);
  const endIndex = existing.indexOf(END_MARKER);

  if (beginIndex !== -1 && endIndex !== -1) {
    const before = existing.slice(0, beginIndex).replace(/\s*$/, "");
    const after = existing.slice(endIndex + END_MARKER.length).replace(/^\s*/, "");
    const trailer = after.length > 0 ? `\n\n${after}\n` : "\n";
    return `${before}\n\n${section}${trailer}`;
  }

  // First run: append the section to the end of the document.
  return `${existing.replace(/\s*$/, "")}\n\n${section}\n`;
}

async function main() {
  const check = process.argv.includes("--check");
  const vifxReport = await runCompatSuite({ adapter: "vifx" });

  if (vifxReport.libraryMatrix.length === 0) {
    throw new Error("The compatibility runner returned no library cases; nothing to generate.");
  }

  const existing = await readFile(docPath, "utf8");
  const section = buildSection(vifxReport);
  const next = spliceSection(existing, section);

  if (check) {
    if (next !== existing) {
      console.error(
        "support-matrix.md library section is out of date. Run: pnpm docs:support-matrix",
      );
      process.exitCode = 1;
      return;
    }
    console.log("support-matrix.md library section is up to date.");
    return;
  }

  if (next === existing) {
    console.log("support-matrix.md library section already up to date.");
    return;
  }

  await writeFile(docPath, next, "utf8");
  console.log(`Updated ${path.relative(repoRoot, docPath)} library compatibility section.`);
}

await main();
